import { jsx as _jsx } from "react/jsx-runtime";
import { slugToTitle } from '@mintlify/common';
import { generateDocsConfig, getFileListSync, getMintIgnore } from '@mintlify/prebuild';
import fse from 'fs-extra';
import pathUtil from 'path';
import { CMD_EXEC_PATH } from '../constants.js';
import { addLog } from '../logging-state.js';
import { InfoLog } from '../logs.js';
const readPackageName = async (directory) => {
    try {
        const packageJson = await fse.readJson(pathUtil.join(directory, 'package.json'));
        if (packageJson && typeof packageJson === 'object' && 'name' in packageJson) {
            const { name } = packageJson;
            if (typeof name === 'string' && name)
                return name.replace(/^@[^/]+\//, '');
        }
    }
    catch { }
    return undefined;
};
/**
 * Lets `mint dev` run on a plain folder of Markdown: when there is no docs.json or mint.json,
 * writes a docs.json whose navigation mirrors the folder structure.
 */
export const ensureDocsConfig = async () => {
    const hasConfig = await Promise.all(['docs.json', 'mint.json'].map((file) => fse.pathExists(pathUtil.join(CMD_EXEC_PATH, file))));
    if (hasConfig.some(Boolean))
        return;
    const mintIgnore = await getMintIgnore(CMD_EXEC_PATH);
    const files = getFileListSync(CMD_EXEC_PATH, CMD_EXEC_PATH, mintIgnore);
    const name = (await readPackageName(CMD_EXEC_PATH)) ??
        (await readPackageName(pathUtil.dirname(CMD_EXEC_PATH))) ??
        slugToTitle(pathUtil.basename(CMD_EXEC_PATH));
    const docsConfig = generateDocsConfig(files, name);
    if (!docsConfig.navigation.groups.length)
        return;
    await fse.writeJson(pathUtil.join(CMD_EXEC_PATH, 'docs.json'), docsConfig, { spaces: 2 });
    addLog(_jsx(InfoLog, { message: "No docs.json found, so one was generated from your folder structure.", detail: "Edit docs.json to customize navigation, theme, and colors." }));
};
